package dk.stream.android;
import org.junit.Test;
import java.io.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;
public class DownloadControlTest {
 @Test public void pauseBlocksUntilResume()throws Exception{DownloadControl control=new DownloadControl();control.pause();ExecutorService worker=Executors.newSingleThreadExecutor();try{Future<Boolean> copy=worker.submit(()->{control.await();return true;});try{copy.get(100,TimeUnit.MILLISECONDS);fail("Download continued while paused");}catch(TimeoutException expected){}control.resume();assertTrue(copy.get(2,TimeUnit.SECONDS));}finally{control.cancel();worker.shutdownNow();}}
 @Test public void cancelUnblocksPausedCopy()throws Exception{DownloadControl control=new DownloadControl();control.pause();ExecutorService worker=Executors.newSingleThreadExecutor();try{Future<Boolean> copy=worker.submit(()->{try{control.await();return false;}catch(InterruptedIOException cancelled){return true;}});control.cancel();assertTrue(copy.get(2,TimeUnit.SECONDS));assertTrue(control.cancelled());}finally{worker.shutdownNow();}}
 @Test public void pauseRevisionAllowsInterruptedNetworkStreamToReconnect(){DownloadControl control=new DownloadControl();int opened=control.revision();control.pause();control.resume();assertNotEquals(opened,control.revision());assertFalse(control.paused());}
 @Test public void resumeCannotReviveCancelledDownload()throws Exception{DownloadControl control=new DownloadControl();control.cancel();control.resume();try{control.await();fail();}catch(InterruptedIOException expected){assertTrue(control.cancelled());}}
 @Test public void zipRemainsValidWhenPausedInTheMiddleOfAFile()throws Exception{DownloadControl control=new DownloadControl();CountDownLatch paused=new CountDownLatch(1);ExecutorService worker=Executors.newSingleThreadExecutor();byte[] original=new byte[16384];for(int i=0;i<original.length;i++)original[i]=(byte)i;ByteArrayOutputStream output=new ByteArrayOutputStream();try{Future<?> copy=worker.submit(()->{try{DownloadArchive.write(java.util.Arrays.asList("one.mp3","two.mp3"),output,(index,destination)->{for(int offset=0;offset<original.length;offset+=1024){if(index==0&&offset==4096){control.pause();paused.countDown();}control.await();destination.write(original,offset,1024);}});}catch(Exception error){throw new RuntimeException(error);}});assertTrue(paused.await(2,TimeUnit.SECONDS));try{copy.get(100,TimeUnit.MILLISECONDS);fail("ZIP completed while paused");}catch(TimeoutException expected){}control.resume();copy.get(2,TimeUnit.SECONDS);try(java.util.zip.ZipInputStream zip=new java.util.zip.ZipInputStream(new ByteArrayInputStream(output.toByteArray()))){assertEquals("one.mp3",zip.getNextEntry().getName());assertArrayEquals(original,zip.readAllBytes());assertEquals("two.mp3",zip.getNextEntry().getName());assertArrayEquals(original,zip.readAllBytes());assertNull(zip.getNextEntry());}}finally{control.cancel();worker.shutdownNow();}}

}
